public class SafeParserCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(SafeParser impl) {
        try {
            return SafeParserChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectParser()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectParser()));
        check("rejects the null that slips past the catch", false, verdict(new NullBlindParser()));
        check("rejects the version that returns 0 instead of the fallback", false, verdict(new ZeroFallbackParser()));
        check("rejects the version that accepts 3.5 as a whole number", false, verdict(new DecimalParser()));
        check("rejects the version with no protection at all", false, verdict(new NoCatchParser()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectParser implements SafeParser {
    public int parseOr(String text, int fallback) {
        try {
            return Integer.parseInt(text);
        } catch (NumberFormatException bad) {
            return fallback;
        }
    }
}

class AlsoCorrectParser implements SafeParser {
    public int parseOr(String text, int fallback) {
        if (text == null) return fallback;
        try {
            return Integer.parseInt(text.trim());
        } catch (RuntimeException bad) {
            return fallback;
        }
    }
}

class NullBlindParser implements SafeParser {
    public int parseOr(String text, int fallback) {
        try {
            return Integer.parseInt(text.trim());
        } catch (NumberFormatException bad) {
            return fallback;
        }
    }
}

class ZeroFallbackParser implements SafeParser {
    public int parseOr(String text, int fallback) {
        try {
            return Integer.parseInt(text);
        } catch (RuntimeException bad) {
            return 0;
        }
    }
}

class DecimalParser implements SafeParser {
    public int parseOr(String text, int fallback) {
        try {
            return (int) Double.parseDouble(text);
        } catch (RuntimeException bad) {
            return fallback;
        }
    }
}

class NoCatchParser implements SafeParser {
    public int parseOr(String text, int fallback) {
        return Integer.parseInt(text);
    }
}

