/**
 * TASK: Write the checks that decide whether a SafeParser is correct.
 *
 *   parseOr(text, fallback) returns the number in text, or fallback when text
 *   is not a whole number. It NEVER throws -- not for null, not for "", not
 *   for "twelve", not for "3.5".
 *   Examples: parseOr("42", -1) -> 42,   parseOr("-7", 0) -> -7,
 *             parseOr("abc", 5) -> 5,    parseOr(null, 9) -> 9,
 *             parseOr("3.5", 1) -> 1,    parseOr("", 8)   -> 8
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. Some broken implementations THROW
 * instead of returning a value, so a crash counts as a failure: wrap your calls
 * in try/catch and return false if anything is thrown.
 *
 * One happy-path call is not a test suite. Choose inputs that expose specific
 * bugs, including the boundary cases named in the contract.
 */
interface SafeParser {
    /* Provided -- do not edit. */
    int parseOr(String text, int fallback);
}

public class SafeParserChecker {

    public static boolean isCorrect(SafeParser impl) {
        try {
            if (impl.parseOr("42", -1) != 42) return false;
            if (impl.parseOr("-7", 0) != -7) return false;
            if (impl.parseOr("abc", 5) != 5) return false;
            if (impl.parseOr("3.5", 1) != 1) return false;
            if (impl.parseOr("", 8) != 8) return false;
            if (impl.parseOr(null, 9) != 9) return false;
            if (impl.parseOr("nope", 0) != 0) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
